#include <dlfcn.h>
#include <stdio.h>
int main() {
  void *handle = dlopen("mylib.so", RTLD_LAZY);
  if (!handle) {
    fprintf(stderr, "%s\n", dlerror());
    return 1;
  }
  typedef void (*myfunc_t)(void);
  myfunc_t myfunc = (myfunc_t)dlsym(handle, "myfunction");
  if (!myfunc) {
    fprintf(stderr, "%s\n", dlerror());
    dlclose(handle);
    return 1;
  }
  myfunc();
  dlclose(handle);
  return 0;
}
